-- Adds optional amenities without changing existing property values.
ALTER TABLE public.properties ADD COLUMN version INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1);
ALTER TABLE public.properties ADD COLUMN car_parking_spaces BIGINT CHECK (car_parking_spaces BETWEEN 0 AND 1000);
ALTER TABLE public.properties ADD COLUMN bike_parking_spaces BIGINT CHECK (bike_parking_spaces BETWEEN 0 AND 1000);
ALTER TABLE public.properties ADD COLUMN parking_type TEXT NOT NULL DEFAULT 'unknown' CHECK (parking_type IN ('unknown', 'none', 'open', 'covered', 'both', 'not_applicable'));
ALTER TABLE public.properties ADD COLUMN parking_allocation TEXT NOT NULL DEFAULT 'unknown' CHECK (parking_allocation IN ('unknown', 'reserved', 'shared', 'not_applicable'));
ALTER TABLE public.properties ADD COLUMN parking_included TEXT NOT NULL DEFAULT 'unknown' CHECK (parking_included IN ('unknown', 'yes', 'no', 'not_applicable'));
ALTER TABLE public.properties ADD COLUMN parking_extra_cost BIGINT CHECK (parking_extra_cost BETWEEN 0 AND 9007199254740991);
ALTER TABLE public.properties ADD COLUMN parking_notes TEXT CHECK (length(parking_notes) <= 2000);
ALTER TABLE public.properties ADD COLUMN parking_source TEXT NOT NULL DEFAULT 'unknown' CHECK (parking_source IN ('unknown', 'observed', 'owner_reported', 'document_checked'));
ALTER TABLE public.properties ADD COLUMN parking_checked_on DATE;
ALTER TABLE public.properties ADD COLUMN electricity_connection TEXT NOT NULL DEFAULT 'unknown' CHECK (electricity_connection IN ('unknown', 'yes', 'no', 'not_applicable'));
ALTER TABLE public.properties ADD COLUMN electricity_meter TEXT NOT NULL DEFAULT 'unknown' CHECK (electricity_meter IN ('unknown', 'separate', 'shared', 'not_applicable'));
ALTER TABLE public.properties ADD COLUMN electricity_phase TEXT NOT NULL DEFAULT 'unknown' CHECK (electricity_phase IN ('unknown', 'single', 'three', 'not_applicable'));
ALTER TABLE public.properties ADD COLUMN power_backup TEXT NOT NULL DEFAULT 'unknown' CHECK (power_backup IN ('unknown', 'none', 'common_areas', 'partial_home', 'full_home', 'not_applicable'));
ALTER TABLE public.properties ADD COLUMN electricity_notes TEXT CHECK (length(electricity_notes) <= 2000);
ALTER TABLE public.properties ADD COLUMN electricity_source TEXT NOT NULL DEFAULT 'unknown' CHECK (electricity_source IN ('unknown', 'observed', 'owner_reported', 'document_checked'));
ALTER TABLE public.properties ADD COLUMN electricity_checked_on DATE;
ALTER TABLE public.properties ADD COLUMN water_municipal TEXT NOT NULL DEFAULT 'unknown' CHECK (water_municipal IN ('unknown', 'yes', 'no', 'not_applicable'));
ALTER TABLE public.properties ADD COLUMN water_borewell TEXT NOT NULL DEFAULT 'unknown' CHECK (water_borewell IN ('unknown', 'yes', 'no', 'not_applicable'));
ALTER TABLE public.properties ADD COLUMN water_tanker TEXT NOT NULL DEFAULT 'unknown' CHECK (water_tanker IN ('unknown', 'yes', 'no', 'not_applicable'));
ALTER TABLE public.properties ADD COLUMN water_supply_frequency TEXT NOT NULL DEFAULT 'unknown' CHECK (water_supply_frequency IN ('unknown', 'daily', 'alternate_days', 'weekly', 'irregular', 'not_applicable'));
ALTER TABLE public.properties ADD COLUMN water_storage_litres BIGINT CHECK (water_storage_litres BETWEEN 0 AND 2147483647);
ALTER TABLE public.properties ADD COLUMN water_connection TEXT NOT NULL DEFAULT 'unknown' CHECK (water_connection IN ('unknown', 'separate', 'shared', 'not_applicable'));
ALTER TABLE public.properties ADD COLUMN water_monthly_charge BIGINT CHECK (water_monthly_charge BETWEEN 0 AND 9007199254740991);
ALTER TABLE public.properties ADD COLUMN maintenance_monthly BIGINT CHECK (maintenance_monthly BETWEEN 0 AND 9007199254740991);
ALTER TABLE public.properties ADD COLUMN water_notes TEXT CHECK (length(water_notes) <= 2000);
ALTER TABLE public.properties ADD COLUMN water_source TEXT NOT NULL DEFAULT 'unknown' CHECK (water_source IN ('unknown', 'observed', 'owner_reported', 'document_checked'));
ALTER TABLE public.properties ADD COLUMN water_checked_on DATE;
